/**
 * 声盾校准 — 批量生成 TTS 合成语音样本（7 音色 × 3 文本）
 */
import ZAI from 'z-ai-web-dev-sdk';
import fs from 'fs';
import path from 'path';

const OUT = path.join(process.cwd(), 'calibration', 'audio');

const TEXTS = [
  '妈，我是小明啊，我手机摔坏了，这是我同学的号码。我在外地出了点事，急需八千块钱周转，你先别问我爸，把钱转到我发你的这个账户上。',
  '今天下午三点在会议室开项目评审会，请准备好上周的测试报告和数据材料，准时参加，不要迟到。',
  'Welcome to the voice shield demonstration. This sentence is generated by a neural text to speech system for calibration purposes.',
];

const VOICES = ['tongtong', 'chuichui', 'xiaochen', 'jam', 'kazi', 'douji', 'luodo'];

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function genWithRetry(zai: Awaited<ReturnType<typeof ZAI.create>>, input: string, voice: string, tries = 5) {
  for (let t = 0; t < tries; t++) {
    try {
      const resp = await zai.audio.tts.create({
        input,
        voice,
        speed: 1.0,
        response_format: 'wav',
        stream: false,
      });
      const ab = await resp.arrayBuffer();
      return Buffer.from(new Uint8Array(ab));
    } catch (e) {
      console.error(`  retry ${t + 1}/${tries}: ${String(e).slice(0, 80)}`);
      await sleep(15000 + t * 15000);
    }
  }
  return null;
}

async function main() {
  const zai = await ZAI.create();
  for (const voice of VOICES) {
    for (let ti = 0; ti < TEXTS.length; ti++) {
      const out = path.join(OUT, `tts_${voice}_${ti}.wav`);
      if (fs.existsSync(out) && fs.statSync(out).size > 1000) {
        console.log('skip', out);
        continue;
      }
      const buf = await genWithRetry(zai, TEXTS[ti], voice);
      if (buf) {
        fs.writeFileSync(out, buf);
        console.log('OK', out, buf.length);
      } else {
        console.error('GIVE UP', voice, ti);
      }
    }
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
